schedule_number_days = payslip._rule_parameter('l10n_mx_schedule_table')[version.schedule_pay]
wage = version._get_contract_wage()

if wage * 12 >= result_rules['ANNUAL_SOCIAL_PROVISION']['total']:
    monthly_amount = payslip._rule_parameter('l10n_mx_uma')['monthly']
else:
    monthly_amount = max(result_rules['ANNUAL_SOCIAL_PROVISION']['total'] - wage * 12, payslip._rule_parameter('l10n_mx_uma')['annually']) / 12

if version.l10n_mx_payment_period_vouchers == 'in_period':
    schedule_factor = schedule_number_days / payslip._rule_parameter('l10n_mx_days_per_month')
else:
    schedule_factor = 1

result = monthly_amount * schedule_factor
